def find_components(grid, color):
    """Find all connected components for a given color"""
    comps = []
    visited = set()
    H, W = len(grid), len(grid[0])
    for y in range(H):
        for x in range(W):
            if grid[y][x] == color and (y, x) not in visited:
                comp = []
                stack = [(y, x)]
                while stack:
                    cy, cx = stack.pop()
                    if (cy, cx) in visited:
                        continue
                    visited.add((cy, cx))
                    comp.append((cy, cx))
                    for dy, dx in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ny, nx = cy+dy, cx+dx
                        if 0 <= ny < H and 0 <= nx < W and grid[ny][nx] == color:
                            stack.append((ny, nx))
                comps.append(comp)
    return comps

for i, demo in enumerate(demos):
    inp = np.array(demo["input"])
    out = np.array(demo["output"])

    # Find background (most frequent)
    inp_counts = Counter(c for row in inp for c in row)
    bg_color = inp_counts.most_common(1)[0][0]
    bg_count = inp_counts[bg_color]

    # Find which non-bg color changes
    changed_color = None
